"""Teacher assistance descriptions and transparent delivery stages."""
from fastapi import Request, HTTPException
TOOLS = {
 'prepare': dict(title='Подготовить урок', short='От цели и темы к понятному плану занятия.', status='Следующий этап', intro='Спланируйте урок под ваш класс: что ученики освоят, как будут практиковаться и как проверить результат.', inputs=['Тема, предмет и возраст учеников','Цель урока и длительность','Особенности класса, исходный план и материалы'], outputs=['План по этапам с распределением времени','Понятные примеры и задания для практики','Способ проверить понимание и запасной вариант'], now='Пока можно сохранить программу и конспект в своих курсах. Автоматическая подготовка и проверка плана ещё не подключены.', steps=['Добавим форму темы, цели, длительности и особенностей класса.','Подключим создание плана и проверку вашего конспекта.','Добавим редактирование и сохранение плана в библиотеку.'], action='/teacher/courses', label='Открыть мои курсы'),
 'adapt': dict(title='Доработать материал', short='Объяснения и задания под уровень вашего класса.', status='Следующий этап', intro='Адаптируйте собственный текст или задание: сделайте объяснение понятнее, добавьте примеры и несколько уровней сложности.', inputs=['Текст объяснения или задания','Возраст и уровень подготовки учеников','Что изменить: сложность, язык, примеры или формат'], outputs=['Переработанный материал с сохранением смысла','Варианты заданий и подсказки','Ответы и пояснения для учителя'], now='Уже можно создавать и редактировать темы и задания в личном банке. Автоматическая адаптация пока не подключена.', steps=['Добавим ввод материала и выбор нужного изменения.','Подключим адаптацию с учётом класса и цели.','Добавим сравнение исходного и нового вариантов, сохранение результата.'], action='/teacher/bank', label='Открыть банк заданий'),
 'library': dict(title='Личная библиотека', short='Курсы, темы и удачные задания всегда под рукой.', status='Уже доступно', intro='Собирайте материалы, которые пригодились на уроках, и возвращайтесь к ним при подготовке следующего занятия.', inputs=['Программа курса или конспект','Темы, упражнения и инструкции','Предмет и класс для поиска'], outputs=['Личные курсы с редактируемым содержанием','Банк тем и заданий с поиском','Импорт курса из TXT, Markdown или JSON и выгрузка JSON'], now='Работают создание, редактирование и поиск курсов, тем и заданий. Материалы доступны только владельцу кабинета.', steps=['Дополним библиотеку отдельными планами уроков.','Свяжем планы, задания и записи одного занятия.','Добавим удобную выгрузку и обмен выбранными материалами.'], action='/teacher/courses', label='Мои курсы'),
 'review': dict(title='Разобрать запись', short='Вернуться к важным моментам проведённого урока.', status='Частично доступно', intro='Прослушайте занятие и сверяйте текст с аудио. В дальнейшем разбор будет строиться вокруг вашего вопроса к уроку.', inputs=['Аудиозапись урока','Нужный фрагмент записи','Вопрос: например, насколько понятной была инструкция'], outputs=['Черновик текста с переходом к фрагментам аудио','Наблюдения с таймкодами — после подключения анализа','Предложения для следующего урока — после подключения анализа'], now='Работают загрузка, прослушивание и обрезка аудио. Для тестовой записи доступны черновики первых пяти минут от трёх моделей. Распознавание новых загрузок автоматически ещё не запускается.', steps=['Выберем распознавание после проверки точности на реальных записях.','Добавим обработку новых записей и понятный прогресс.','Подключим разбор по вопросу учителя с указанием фрагментов и неопределённости.'], action='/account', label='Открыть записи уроков'),
 'resources': dict(title='Найти полезные материалы', short='Подборка под тему, класс и вашу задачу.', status='В планах', intro='Находите учебные и педагогические материалы с понятным объяснением, как использовать их на вашем уроке.', inputs=['Тема или педагогический вопрос','Предмет, класс и язык','Нужный формат: курс, статья, упражнение или методика'], outputs=['Подборка с проверяемыми ссылками на источники','Краткое описание и условия доступа','Рекомендации по применению и сохранение ссылок'], now='Внешний поиск и каталог пока не подключены. Собственные подборки и ссылки можно сохранить в курсах и банке тем.', steps=['Соберём проверенные источники и школьные подборки.','Добавим поиск с проверкой ссылок и указанием источника.','Свяжем рекомендации с темой курса и вопросами после урока.'], action='/teacher/bank', label='Сохранить свою подборку')
}
def install(app):
    from app.main import page, current_user
    @app.get('/teacher/help')
    def overview(request: Request):
        return page(request,'assistant',user=current_user(request),tools=TOOLS,tool=None,slug='',page_title='Помощь учителю')
    @app.get('/teacher/help/{slug}')
    def detail(slug: str, request: Request):
        if slug not in TOOLS: raise HTTPException(404,'Раздел не найден')
        return page(request,'assistant',user=current_user(request),tools=TOOLS,tool=TOOLS[slug],slug=slug,page_title=TOOLS[slug]['title'])
